function F({registerIndicator:A,sourceValues:D,nulls:s}){A({id:"oa-regchannel",name:"Regression Channels (REGCHANNEL)",category:"Channels",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:20,min:2,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"},{key:"multiplier",type:"number",label:"Standard Deviation Multiplier",default:2,min:.1,max:100,step:.1,tooltip:"Band distance as a multiple of the root mean square residual of the regression fit."}],plots:[{key:"upper",type:"line",title:"Upper Band",style:{color:"#ffeb3b",lineWidth:2}},{key:"mid",type:"line",title:"Regression Line",style:{color:"#ffeb3b",lineWidth:2}},{key:"lower",type:"line",title:"Lower Band",style:{color:"#ffeb3b",lineWidth:2}}],fills:[{between:["upper","mid"],colorUp:"#ef5350",colorDown:"#ef5350",opacity:.1},{between:["mid","lower"],colorUp:"#26a69a",colorDown:"#26a69a",opacity:.1}],calc(d,c){const o=Math.max(2,Math.floor(Number(c.period)||20)),y=Math.max(.1,Number(c.multiplier)||2),b=D(d,c.source??"close"),r=d.length,h=new Array(r).fill(NaN),N=new Array(r).fill(NaN),k=new Array(r).fill(NaN);let i=0,w=0;for(let e=0;e<o;e++)i+=e,w+=e*e;const n=o,u=n*w-i*i;for(let e=o-1;e<r&&!(!Number.isFinite(u)||u===0);e++){let p=0,g=0,x=!0;for(let t=0;t<o;t++){const l=b[e-o+1+t];if(!Number.isFinite(l)){x=!1;break}p+=l,g+=t*l}if(!x)continue;const m=(n*g-i*p)/u,M=(p-m*i)/n,a=m*(o-1)+M;let R=0;for(let t=0;t<o;t++){const l=b[e-o+1+t]-(m*t+M);R+=l*l}const f=Math.sqrt(R/n);!Number.isFinite(a)||!Number.isFinite(f)||(N[e]=a,h[e]=a+y*f,k[e]=a-y*f)}return{upper:s(h),mid:s(N),lower:s(k)}}})}export{F as default};
